import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PINS = [2, 3, 4]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
                print(f"GPIO {pin} set as output (active_high=True)")
            except GPIODeviceError as exc:
                print(f"Error: cannot open GPIO {pin}: {exc}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)

        while _running:
            for dev in devices:
                try:
                    if dev.is_active:
                        state = "HIGH"
                    else:
                        state = "LOW"
                    print(f"GPIO {dev.pin.number} -> {state}")
                except GPIODeviceClosed:
                    print(f"Warning: device on GPIO {dev.pin.number} closed unexpectedly", file=sys.stderr)
            time.sleep(INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

