import time
import signal
import sys
import traceback

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

CAPTURE_INTERVAL_SECONDS = 60
IMAGE_PATH = "captured_image.jpg"

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def capture_image(image_path: str) -> bool:
    """Capture a single image and save it to the given path.

    Returns True on success, False on failure.
    """
    picam2 = None
    try:
        picam2 = Picamera2()
        still_config = picam2.create_still_configuration()
        picam2.configure(still_config)
        picam2.start()
        picam2.capture_file(image_path)
        print(f"Image captured and saved to {image_path}")
        return True
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        traceback.print_exc()
        return False
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
            try:
                picam2.close()
            except Exception:
                pass

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        while _running:
            if not capture_image(IMAGE_PATH):
                return 1
            for _ in range(CAPTURE_INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        traceback.print_exc()
        return 1
    return 0

if __name__ == "__main__":
    sys.exit(main())

