import time
import signal
import sys
from gpiozero import PWMOutputDevice

# PCA9685 channel 0 duty cycle range (0-65535)
DUTY_MIN, DUTY_MAX = 0, 65535
SAMPLE_INTERVAL = 0.05

# Global so the signal handler can reach it
_running = True
_pwm = None


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _read_pwm(pwm):
    """Return the current duty-cycle value, or None on error."""
    try:
        return pwm.value
    except Exception as exc:
        print(f"Error reading PWM value: {exc}", file=sys.stderr)
        return None


def _check_valid(value):
    """Reject readings outside the PCA9685's 12-bit duty-cycle range."""
    if value is None:
        return False
    if not isinstance(value, (int, float)):
        return False
    if not (DUTY_MIN <= value <= DUTY_MAX):
        print(f"Warning: value {value} out of range [{DUTY_MIN}, {DUTY_MAX}]", file=sys.stderr)
        return False
    return True


def main():
    global _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _pwm = PWMOutputDevice(0)
    except Exception as exc:
        print(f"Failed to initialize PWM on channel 0: {exc}", file=sys.stderr)
        sys.exit(1)

    print("PCA9685 channel 0 PWM value: 0")
    try:
        while _running:
            value = _read_pwm(_pwm)
            if _check_valid(value):
                print(f"PCA9685 channel 0 PWM value: {value}")
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if _pwm is not None:
            _pwm.close()
        print("Program stopped.")


if __name__ == "__main__":
    main()

