import time
import signal
import sys
from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

ECHO_PIN = 17
TRIG_PIN = 22
CYCLES = 5
DELAY_SECONDS = 50

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIG_PIN, max_distance=4.0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                print("Interrupted before completion.")
                break

            try:
                distance = sensor.distance * 100.0
                print(f"Cycle {i + 1}/{CYCLES} - Distance: {distance:.2f} cm")
            except DeviceClosed:
                print("Sensor device closed unexpectedly.", file=sys.stderr)
                break
            except Exception as exc:
                print(f"Cycle {i + 1}/{CYCLES} - Read error: {exc}", file=sys.stderr)

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY_SECONDS)
    finally:
        try:
            sensor.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

