import time
import signal
import sys
import numpy as np
from picamera2 import Picamera2

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

cam = Picamera2()
try:
    cam.configure(cam.create_still_configuration())
    cam.start()
    print("Camera started. Capturing images every 2 seconds. Press Ctrl+C to stop.")

    while running:
        try:
            frame = cam.capture_array()
            if frame is None or frame.size == 0:
                print("Warning: captured frame is empty, skipping.")
                continue
            if frame.dtype != np.uint8:
                frame = frame.astype(np.uint8)
            if frame.ndim == 3 and frame.shape[2] == 3:
                print("Image captured successfully.")
            else:
                print("Warning: captured image format may be invalid.")
        except Exception as e:
            print(f"Error capturing image: {e}")
            break

        time.sleep(2)

except Exception as e:
    print(f"Failed to initialize camera: {e}")
finally:
    try:
        cam.stop()
    except Exception:
        pass
    try:
        cam.close()
    except Exception:
        pass
    print("Camera resources released. Exiting.")
    sys.exit(0)

