                print(f"Failed to init DHT22 on pin {pin}: {exc}", file=sys.stderr)
        while running:
            for s in sensors:
                try:
                    if s.temperature is None or s.humidity is None:
                        raise RuntimeError("invalid reading")
                    report(s.temperature, s.humidity)
                except Exception as exc:
                    print(f"Read error on pin {s.pin}: {exc}", file=sys.stderr)
            if running:
                time.sleep(INTERVAL)
    finally:
        for s in sensors:
            try:
                s.exit()
            except Exception:
                pass

