import smbus2
import time
import signal
import sys

I2C_BUS = 1
PCA9685_ADDR = 0x40
SAMPLE_INTERVAL = 0.15

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_pca9685(bus, addr):
    """Read a 16-bit signed value from the PCA9685 channel register (0x00)."""
    try:
        data = bus.read_i2c_block_data(addr, 0x00, 2)
        if len(data) < 2:
            raise IOError("short read")
        raw = (data[0] << 8) | data[1]
        if raw >= 0x8000:
            raw -= 0x10000
        return raw
    except OSError as e:
        raise IOError(f"I2C read failed: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                value = read_pca9685(bus, PCA9685_ADDR)
                print(value)
            except IOError as e:
                print(f"Error: {e}", file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        bus.close()
        print("Exited cleanly.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data line on GPIO 4 (board.D4) and GPIO 17 (board.D17)
# We use both pins so the program runs even if one physical connection is faulty.
PINS = [board.D4, board.D17]
READ_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def report(sensor):
    """Return a human-readable state string for one DHT22 reading."""
    if sensor is None:
        return "sensor unavailable"
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is None or hum is None:
            return "no data"
        return f"{temp:.1f}C / {hum:.1f}%"
    except RuntimeError as e:
        return f"read error: {e}"

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Try each pin in turn until one succeeds.
    for pin in PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            print(f"DHT22 initialised on {pin}")
            break
        except Exception as e:
            print(f"init failed on {pin}: {e}")
            sensor = None

    if sensor is None:
        print("DHT22 not available on any pin; exiting.")
        sys.exit(1)

    try:
        while _running:
            state = report(sensor)
            print(state)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"unexpected error: {e}")
    finally:
        try:
            sensor.exit()
        except Exception:
            pass
        print("DHT22 released. Exiting.")

if __name__ == "__main__":
    main()

