import signal
import sys
import numpy as np
from picamera2 import Picamera2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def capture_image(camera):
    """Capture a single image and return a valid numpy array, or None on failure."""
    try:
        frame = camera.capture_array()
        if frame is None or frame.size == 0:
            print("Error: captured frame is empty", file=sys.stderr)
            return None
        if frame.dtype != np.uint8:
            frame = frame.astype(np.uint8)
        return frame
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return None

def save_image(image, filename):
    """Save a numpy image array to disk. Returns True on success, False on failure."""
    try:
        from PIL import Image
        Image.fromarray(image).save(filename, format='PNG')
        return True
    except Exception as e:
        print(f"Error saving image: {e}", file=sys.stderr)
        return False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    camera = None
    try:
        camera = Picamera2()
        camera.start()
        print("Camera initialized and started.")

        for i in range(3):
            if not _running:
                print("Interrupted by user.")
                break

            image = capture_image(camera)
            if image is None:
                print(f"Cycle {i+1}: capture failed, aborting.")
                break

            filename = f"image_{i+1}.png"
            if save_image(image, filename):
                print(f"Saved {filename}")
            else:
                print(f"Cycle {i+1}: save failed.")

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if camera is not None:
            try:
                camera.stop()
                camera.close()
                print("Camera resources released.")
            except Exception as e:
                print(f"Error releasing camera: {e}", file=sys.stderr)

