import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x29
READ_INTERVAL = 0.01

# TCS34725 register addresses
REG_ID = 0x00
REG_CMD = 0x01
REG_DATA = 0x02
REG_STATUS = 0x03

# Validity flags
VALID_MASK = 0x03

def read_color(bus):
    """Read and validate a color from the TCS34725."""
    # Read 6 bytes: ID, command, data, status
    msg = i2c_msg.read(I2C_ADDR, 6)
    bus.i2c_rdwr(msg)
    data = list(msg)

    if len(data) != 6:
        return None

    chip_id = data[0]
    if chip_id != 0x29:
        return None

    cmd = data[1]
    if (cmd & 0x01) != 0:
        return None

    status = data[5]
    if (status & VALID_MASK) != 0:
        return None

    return data[2] | (data[3] << 8)

def main():
    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    def cleanup(signum=None, frame=None):
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            color = read_color(bus)
            if color is not None:
                print(f"Color: {color}")
            else:
                print("Error: invalid reading from TCS34725")
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

