import time
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
ADC_ADDRESS = 0x48
ADC_SAMPLES_PER_SECOND = 128000
SAMPLE_INTERVAL = 0.5
VALID_CHANNEL = 0

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_adc():
    """Initializes the I2C bus and ADS1115 ADC.

    Returns:
        tuple: (i2c, ads, channel) on success, or (None, None, None) on failure.
    """
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None, None, None

    try:
        ads = ADS.ADS1115(i2c, address=ADC_ADDRESS)
        ads.gain = 1
        ads.data_rate = ADC_SAMPLES_PER_SECOND
    except ValueError as e:
        print(f"Error: ADS1115 not found at address 0x{ADC_ADDRESS:02X}: {e}", file=sys.stderr)
        return None, None, None
    except Exception as e:
        print(f"Error initializing ADS1115: {e}", file=sys.stderr)
        return None, None, None

    try:
        channel = AnalogIn(ads, VALID_CHANNEL)
    except Exception as e:
        print(f"Error initializing channel {VALID_CHANNEL}: {e}", file=sys.stderr)
        return None, None, None

    return i2c, ads, channel

def read_adc_value(channel):
    """Reads the raw ADC value from the specified channel.

    Args:
        channel: The AnalogIn object for the desired channel.

    Returns:
        int: The raw ADC value, or None if the reading fails.
    """
    try:
        return channel.value
    except Exception as e:
        print(f"Error reading ADC value: {e}", file=sys.stderr)
        return None

def main():
    """Main function to continuously read and print ADC values."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c, ads, channel = initialize_adc()
    if i2c is None or ads is None or channel is None:
        sys.exit(1)

    try:
        while _running:
            adc_value = read_adc_value(channel)
            if adc_value is not None:
                print(f"ADC Value: {adc_value}")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        # Clean up resources
        try:
            if 'ads' in locals():
                ads.gain = 1
                ads.data_rate = ADC_SAMPLES_PER_SECOND
        except Exception:
            pass
        try:
            if 'channel' in locals():
                channel.close()
        except Exception:
            pass
        try:
            if 'i2c' in locals():
                i2c.deinit()
        except Exception:
            pass
        print("ADC reading stopped.")

if __name__ == "__main__":
    main()

