                        state = "HIGH"
                    else:
                        state = "LOW"
                    print(f"GPIO {dev.pin.number} -> {state}")
                except DeviceClosed:
                    print(f"Warning: device GPIO {dev.pin.number} closed unexpectedly", file=sys.stderr)
                    return 1
                except GPIOZeroError as exc:
                    print(f"Warning: read error on GPIO {dev.pin.number}: {exc}", file=sys.stderr)
                    return 1

            time.sleep(INTERVAL)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


