import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x77
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_bme680(bus):
    """Read one 6-byte measurement from the BME680 and validate it."""
    data = bus.read_i2c_block_data(I2C_ADDR, 0x80, 6)
    if len(data) != 6:
        raise IOError(f"Short read: expected 6 bytes, got {len(data)}")

    # BME680 6-byte block at register 0x80: [status, pres, t, p, h, ctrl_meas]
    status = data[0]
    if status & 0x1:
        raise IOError(f"BME680 status bit 0 set (unfinished)")
    if status & 0x2:
        raise IOError(f"BME680 status bit 1 set (unfinished)")
    if status & 0x4:
        raise IOError(f"BME680 status bit 2 set (unfinished)")
    if status & 0x8:
        raise IOError(f"BME680 status bit 3 set (unfinished)")

    pres = data[1] | (data[2] << 8)
    if pres < 0x0100 or pres > 0x07FF:
        raise IOError(f"Pressure out of range: {pres}")

    t = data[3] | (data[4] << 8)
    if t < -40 or t > 85:
        raise IOError(f"Temperature out of range: {t}")

    p = data[4] | (data[5] << 8)
    if p < 0x0100 or p > 0x07FF:
        raise IOError(f"Humidity out of range: {p}")

    return pres, t, p


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device with a zero-length write to confirm it is present.
        try:
            msg = i2c_msg.write(I2C_ADDR, [])
            bus.i2c_rdwr(msg)
        except OSError:
            print(f"Error: no device found at 0x{I2C_ADDR:02X} on bus {I2C_BUS}", file=sys.stderr)
            sys.exit(1)

        while _running:
            try:
                pres, t, p = _read_bme680(bus)
                print(f"Pressure: {pres} hPa, Temperature: {t} C, Humidity: {p} %")
            except IOError as exc:
                print(f"Error: failed to read BME680: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Error: unexpected read failure: {exc}", file=sys.stderr)

            time.sleep(READ_INTERVAL_S)
    finally:
        bus.close()
        print("\nExiting cleanly.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# DHT11 data line on GPIO 17 (BCM) and GPIO 18 (BCM)
DHT_PINS = (board.D17, board.D18)
READ_INTERVAL = 0.5
CYCLES = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT11 on each pin; use the first that succeeds.
    sensor = None
    for pin in DHT_PINS:
        try:
            sensor = adafruit_dht.DHT11(pin, use_pulseio=False)
            print(f"DHT11 initialized on {pin.pin_name} (BCM {pin.pin_number})")
            break
        except Exception as exc:
            print(f"Failed to initialize DHT11 on {pin.pin_name}: {exc}", file=sys.stderr)
            sensor = None

    if sensor is None:
        print("Error: No DHT11 sensor found on GPIO 17 or GPIO 18.", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                print("\nInterrupted by user; exiting early.", file=sys.stderr)
                break

            try:
                temp = sensor.temperature
                hum = sensor.humidity
                if temp is None or hum is None:
                    print(f"Cycle {i + 1}/{CYCLES}: sensor returned None (no data).")
                else:
                    print(f"Cycle {i + 1}/{CYCLES}: Temperature = {temp:.1f} C, Humidity = {hum:.1f} %")
            except RuntimeError as exc:
                # DHT11 checksum / timing errors are common; report and continue.
                print(f"Cycle {i + 1}/{CYCLES}: read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Cycle {i + 1}/{CYCLES}: unexpected error: {exc}", file=sys.stderr)

            if i < CYCLES - 1:
                time.sleep(READ_INTERVAL)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass
        print("DHT11 sensor released.")

if __name__ == "__main__":
    main()

