import time
import signal
import sys
import numpy as np
from picamera2 import Picamera2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def capture_image(camera):
    """Capture a single image and return it as a NumPy array.

    Returns None on failure so the caller can skip the cycle.
    """
    try:
        image = camera.capture_array()
        if image is None or image.size == 0:
            print("Warning: captured image is empty", file=sys.stderr)
            return None
        return image
    except Exception as exc:
        print(f"Warning: capture failed: {exc}", file=sys.stderr)
        return None

def save_image(image, filename):
    """Save a NumPy image array to disk using JPEG compression."""
    try:
        from PIL import Image
        Image.fromarray(image).save(filename, "JPEG", quality=90)
    except Exception as exc:
        print(f"Warning: failed to save image: {exc}", file=sys.stderr)

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    camera = None
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        print("Camera initialized; starting capture...")

        cycles = 0
        while _running and cycles < 2:
            image = capture_image(camera)
            if image is not None:
                timestamp = time.strftime("%Y%m%d-%H%M%S")
                filename = f"image_{timestamp}.jpg"
                save_image(image, filename)
