import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
PCA9685_ADDR = 0x40
REG_MODE1 = 0x00
REG_PRESCALE = 0xFE
REG_LED0_ON_L = 0x06

running = True
bus = None


def _signal_handler(signum, frame):
    global running
    running = False


def _read_u16(bus, addr, reg):
    msg = i2c_msg.write(addr, [reg])
    read = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(msg, read)
    return int.from_bytes(read.buf[0:2], byteorder='little')


def _read_s16(bus, addr, reg):
    val = _read_u16(bus, addr, reg)
    return val - 0x10000 if val >= 0x8000 else val


def _write_u16(bus, addr, reg, val):
    bus.write_word_data(addr, reg, val & 0xFFFF)


def _write_s16(bus, addr, reg, val):
    _write_u16(bus, addr, reg, val & 0xFFFF)
    if val < 0:
        _write_u16(bus, addr, reg + 1, (0xFFFF - (0xFFFF - val)) & 0xFFFF)


def _init_pca9685(bus, addr):
    mode1 = _read_u16(bus, addr, REG_MODE1)
    # Sleep
    _write_u16(bus, addr, REG_MODE1, mode1 | 0x10)
    # 25 kHz default
    _write_u16(bus, addr, REG_PRESCALE, 0x200)
    time.sleep(0.005)
    _write_u16(bus, addr, REG_MODE1, mode1)


def main():
    global bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_pca9685(bus, PCA9685_ADDR)
        print(f"PCA9685 ready at 0x{PCA9685_ADDR:02X}")

        while running:
            try:
                val = _read_s16(bus, PCA9685_ADDR, REG_LED0_ON_L)
                print(f"Measurement: {val}")
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
            time.sleep(0.1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

# Serial port configuration
PORT = '/dev/serial0'  # Default UART on Raspberry Pi (GPIO 14/15)
BAUDRATE = 9600
TIMEOUT_S = 1.0

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def open_serial_port():
    """Open the serial port with error handling."""
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUDRATE,
            timeout=TIMEOUT_S,
            write_timeout=TIMEOUT_S,
        )
        print(f"Opened {PORT} @ {BAUDRATE} baud")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {PORT}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening {PORT}: {e}", file=sys.stderr)
        return None


def read_data(ser):
    """Read one line from the serial port and validate it."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS read error: {e}", file=sys.stderr)
        return None

    if not raw:
        # Timeout with no data; device may be absent or not responding
        return None

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Decode error: {e}", file=sys.stderr)
        return None

    if not data:
        return None

    return data


def process_data(data):
    """Process the received data (placeholder for actual logic)."""
    print(f"Received: {data}")


def main():
    """Main loop: read and process data until interrupted."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            start = time.monotonic()

            data = read_data(ser)
            if data is None:
                # Brief pause to avoid busy-looping on unresponsive devices
                elapsed = time.monotonic() - start
                if elapsed < 0.1:
                    time.sleep(0.1 - elapsed)
                continue

            try:
                process_data(data)
            except Exception as e:
                print(f"Processing error: {e}", file=sys.stderr)

            elapsed = time.monotonic() - start
            remaining = 0.1 - elapsed
            if remaining > 0:
                time.sleep(remaining)

    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

