import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 not installed. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True
bus = None


def _cleanup():
    global bus
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
        bus = None


def _handle_signal(signum, frame):
    global running
    running = False


def _read_word(bus, addr, reg):
    """Read a signed 16-bit word from two consecutive registers."""
    try:
        high = bus.read_byte_data(addr, reg)
        low = bus.read_byte_data(addr, reg + 1)
    except OSError as e:
        raise RuntimeError(f"I2C read failed at register 0x{reg:02X}: {e}") from e

    val = (high << 8) | low
    if val >= 0x8000:
        val -= 0x10000
    return val


def _init_mpu6050(bus, addr):
    """Wake the MPU6050 by clearing the sleep bit in PWR_MGMT_1."""
    try:
        bus.read_byte_data(addr, PWR_MGMT_1)
    except OSError:
        raise RuntimeError(f"No device found at 0x{addr:02X}")

    try:
        bus.write_byte_data(addr, PWR_MGMT_1, 0x00)
    except OSError as e:
        raise RuntimeError(f"Failed to wake MPU6050: {e}") from e

    time.sleep(0.1)


def main():
    global bus

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_mpu6050(bus, MPU6050_ADDR)
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                accel_x = _read_word(bus, MPU6050_ADDR, ACCEL_XOUT_H)
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)
                break

            if accel_x < -32768 or accel_x > 32767:
                print(f"Warning: accelerometer value out of range: {accel_x}", file=sys.stderr)
                continue

            print(f"Accelerometer X: {accel_x}")
            return accel_x
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

