import smbus2
import time
import signal
import sys

I2C_BUS = 1
TSL2591_ADDR = 0x29
READ_INTERVAL = 10
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_raw(bus):
    """Trigger a single-shot measurement and return the 16-bit result."""
    # Write 0x1E (0001 1110) to the command register to start a single-shot
    # integration with the default gain and integration time.
    bus.write_byte_data(TSL2591_ADDR, 0x00, 0x1E)
    # Wait for the conversion to complete (max ~180 ms for 1x gain, 100 ms for 180 ms)
    deadline = time.monotonic() + 0.2
    while True:
        status = bus.read_byte_data(TSL2591_ADDR, 0x00)
        if (status & 0x80) != 0:
            break
        if time.monotonic() > deadline:
            raise TimeoutError("TSL2591 conversion timed out")
        time.sleep(0.005)
    # Read the 16-bit result from the command register (bits 15:0)
    return bus.read_word_data(TSL2591_ADDR, 0x00)

def _check_valid(raw):
    """Return True only when the device has finished a valid conversion."""
    if raw == 0 or raw == 0xFFFF:
        return False
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            try:
                raw = _read_raw(bus)
            except OSError as e:
                print(f"Error: I2C communication failure: {e}", file=sys.stderr)
                break
            except TimeoutError as e:
                print(f"Error: TSL2591 conversion failed: {e}", file=sys.stderr)
                break

            if not _check_valid(raw):
                print("Warning: Invalid reading (device not ready or timeout). Skipping.", file=sys.stderr)
                continue

            print(f"Reading {readings_taken + 1}/{NUM_READINGS}: {raw}")
            readings_taken += 1

            if readings_taken < NUM_READINGS and _running:
                time.sleep(READ_INTERVAL)

        if not _running:
            print("\nInterrupted by user. Exiting.")
    finally:
        bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

