import signal
import sys
import board
import adafruit_dht

# Global handle so the signal handler can release the device.
_sensor = None

def cleanup(signum=None, frame=None):
    """Release the DHT22 hardware on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the DHT22 on GPIO 4 (board.D4).
    try:
        _sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, 4):
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is None or humidity is None:
                    print(f"Cycle {cycle}: sensor returned None (sensor absent or bus error)")
                else:
                    print(f"Cycle {cycle}: Temperature = {temperature:.1f} C  Humidity = {humidity:.1f} %")

            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; report and continue.
                print(f"Cycle {cycle}: read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Cycle {cycle}: unexpected error: {exc}", file=sys.stderr)

            time.sleep(2.0)

    finally:
        cleanup()

if __name__ == "__main__":
    main()
